node --input-type=module - <<'NODE'
import { chromium } from 'playwright';
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/google-chrome', args: ['--no-sandbox', '--disable-gpu'] });
const page = await browser.newPage();
await page.goto('http://127.0.0.1:4174/');
await page.locator('.run-row').nth(1).locator('.model-cell a').click();
await page.waitForURL(/runs\/rendered\/openai-gpt-5-4-mini-max-codex-20260812\.html$/);
await page.waitForLoadState('networkidle');
const title = await page.title();
const forecast = await page.locator('#metricForecastValue').textContent();
const rows = await page.locator('#forecastRows tr').count();
console.log(JSON.stringify({ url: page.url(), title, forecast, rows }, null, 2));
await browser.close();
NODE
